/*
 * RTL INFERENCE PSEUDOCODE
 * ========================
 * Input: signed [WEIGHT_BITS-1:0] feat [0:INPUT_DIM-1]  (pre-scaled by WEIGHT_SCALE)
 *
 * Layer 0 (9->128):
 *   for i in 0..127:
 *     acc = L0_B[i]
 *     for j in 0..8:
 *       acc += L0_W[i*9+j] * feat[j]
 *     acc >>= log2(WEIGHT_SCALE)   // re-normalize
 *     h0[i] = (acc > 0) ? acc : 0  // ReLU
 *
 * Layer 1 (128->128): same pattern with L1_W, L1_B, h0->h1
 * Layer 2 (128->64):  same pattern with L2_W, L2_B, h1->h2
 *
 * Output (64->3):
 *   for i in 0..2:
 *     logit[i] = L3_B[i]
 *     for j in 0..63:
 *       logit[i] += L3_W[i*64+j] * h2[j]
 *     logit[i] >>= log2(WEIGHT_SCALE)
 *
 * Decision: action = argmax(logit[0], logit[1], logit[2])
 *   0=HOLD, 1=BUY, 2=SELL
 */